<script lang="ts">
 import type {Project} from "./model";import {translator} from "./i18n";import {displayDate} from "./date-format";import {Layers3,ReceiptText,Gauge,Plus,Trash2,Save} from "@lucide/svelte";
 export let project:Project;export let draft:any;export let ontariffs:()=>void;
 import ReferencePicker from "./ReferencePicker.svelte";import type {ReferenceKind} from "./catalog-definitions";
 export let onreference:(kind:ReferenceKind)=>void;
 let tab="main",meterType="";$:t=translator(project.settings.language);$:language=project.settings.language;
 const tabs=[{id:"main",ru:"Основное",ro:"General",icon:Layers3},{id:"tariffs",ru:"Тарифы",ro:"Tarife",icon:ReceiptText},{id:"meters",ru:"Приборы учёта",ro:"Contoare",icon:Gauge}];
</script>
<div class="service-editor">
 <label class="service-field">{t("Наименование","Denumire")}<input bind:value={draft.name[language]}/></label>
 <div class="service-tabs" role="tablist" aria-label={t("Карточка услуги","Fișa serviciului")}>{#each tabs as item}<button type="button" role="tab" aria-selected={tab===item.id} onclick={()=>tab=item.id}><item.icon size={16}/>{item[language]}</button>{/each}</div>
 <div class="service-tab-content" role="tabpanel">
 {#if tab==="main"}
  <div class="service-field"><span>{t("Вид услуги","Tip de serviciu")}</span><ReferencePicker {project} kind="service-types" bind:value={draft.service_type} onopen={onreference}/></div>
  <div class="service-field"><span>{t("Поставщик","Furnizor")}</span><ReferencePicker {project} kind="counterparties" bind:value={draft.provider} onopen={onreference}/></div>
  <div class="service-pair"><label class="service-field">{t("Порядок в отчётах","Ordine în rapoarte")}<input type="number" min="0" max="10000" value={draft.report_order??0} onchange={e=>draft.report_order=Number(e.currentTarget.value)}/></label><label class="service-field">{t("Единица измерения","Unitate de măsură")}<input bind:value={draft.unit}/></label></div>
  <label class="service-field">{t("Основание расчёта","Baza de calcul")}<select bind:value={draft.calculation_type}><option value="metered">{t("Показания прибора учёта","Indexurile contorului")}</option><option value="person">{t("Количество проживающих за месяц","Numărul locatarilor din lună")}</option><option value="area">{t("Общая площадь","Suprafața totală")}</option><option value="fixed">{t("Фиксированный объём на счёт","Volum fix pe cont")}</option><option value="manual">{t("Ручной объём за месяц","Volum lunar manual")}</option></select></label>
  {#if draft.calculation_type==="fixed"}<label class="service-field">{t("Объём по умолчанию","Volum implicit")}<input bind:value={draft.default_quantity}/></label>{/if}
  <label class="check-row"><input type="checkbox" bind:checked={draft.active}/>{t("Услуга активна","Serviciu activ")}</label>
  <details open={!draft.name.ru||!draft.name.ro}><summary>{t("Названия на других языках","Denumiri în alte limbi")}</summary><div class="service-translations"><label class="service-field">Русский<input bind:value={draft.name.ru}/></label><label class="service-field">Română<input bind:value={draft.name.ro}/></label><label class="service-field">English<input bind:value={draft.name.en}/></label></div></details>
  <label class="service-field">{t("Примечание","Notă")}<textarea rows="2" bind:value={draft.notes}></textarea></label>
 {:else if tab==="tariffs"}
  <div class="service-editor-toolbar"><button type="button" class="button secondary" onclick={ontariffs}><Save size={16}/><ReceiptText size={16}/>{t("Сохранить и открыть тарифы","Salvează și deschide tarifele")}</button></div>
  <div class="service-editor-table"><table><thead><tr><th>{t("Действует с","Valabil din")}</th><th>{t("Тариф, MDL","Tarif, MDL")}</th></tr></thead><tbody>{#each project.tariffs.filter(r=>r.service_id===draft.id).sort((a,b)=>b.effective_from.localeCompare(a.effective_from)) as rate}<tr><td>{displayDate(rate.effective_from,project)}</td><td>{rate.rate}</td></tr>{:else}<tr><td colspan="2">{t("Тариф не задан","Tariful nu este stabilit")}</td></tr>{/each}</tbody></table></div>
 {:else}
  <div class="service-editor-toolbar"><input aria-label={t("Вид прибора учёта","Tip de contor")} placeholder={t("Вид прибора учёта","Tip de contor")} bind:value={meterType}/><button type="button" class="button secondary" disabled={!meterType.trim()} onclick={()=>{draft.meter_types=[...(draft.meter_types||[]),meterType.trim()];meterType="";}}><Plus size={16}/>{t("Добавить","Adaugă")}</button></div>
  <div class="service-editor-table"><table><thead><tr><th>{t("Виды приборов учёта","Tipuri de contoare")}</th><th></th></tr></thead><tbody>{#each draft.meter_types||[] as type,i}<tr><td>{type}</td><td><button class="icon-button" aria-label={t("Убрать вид прибора","Elimină tipul contorului")} onclick={()=>draft.meter_types=draft.meter_types.filter((_:string,index:number)=>index!==i)}><Trash2 size={16}/></button></td></tr>{:else}<tr><td colspan="2">{t("Виды приборов не указаны","Tipurile contoarelor nu sunt indicate")}</td></tr>{/each}</tbody></table></div>
  <div class="service-editor-table"><table><thead><tr><th>{t("Прибор / номер","Contor / număr")}</th><th>{t("Счёт","Cont")}</th><th>{t("Состояние","Stare")}</th><th>{t("Установка / снятие","Instalare / demontare")}</th></tr></thead><tbody>{#each project.meters.filter(m=>m.service_id===draft.id) as m}<tr><td>{m.label} · {m.serial_number}</td><td>{project.accounts.find(a=>a.id===m.account_id)?.number||t("Общий","Comun")}</td><td>{m.active?t("Активен","Activ"):t("Отключён","Dezactivat")}</td><td>{displayDate(m.installed_on,project)} / {displayDate(m.retired_on,project)}</td></tr>{:else}<tr><td colspan="4">{t("Физические приборы не подключены","Nu sunt conectate contoare fizice")}</td></tr>{/each}</tbody></table></div>
 {/if}
 </div>
</div>
<style>.service-editor{display:flex;flex-direction:column;gap:16px;min-height:380px}.service-field{display:grid!important;grid-template-columns:145px minmax(0,1fr);gap:14px;align-items:center;font-size:12px}.service-field input,.service-field textarea,.service-field select{min-width:0;width:100%}.service-tabs{display:flex;gap:4px;flex-wrap:wrap;border-bottom:1px solid var(--border)}.service-tabs button{display:flex;gap:8px;align-items:center;padding:10px 14px;background:transparent;border:0;color:var(--text);border-bottom:2px solid transparent}.service-tabs button[aria-selected="true"]{border-bottom-color:var(--accent)}.service-tab-content{display:flex;flex-direction:column;gap:18px;min-height:280px}.service-pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.service-pair .service-field{grid-template-columns:110px minmax(0,1fr)}.service-editor-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.service-editor-toolbar input{flex:1;min-width:120px}.service-editor-table{overflow:auto;flex:none;min-height:120px;max-height:280px}.service-editor-table table{width:100%;min-width:400px;margin:0}.service-editor-table th{position:sticky;top:0;background:var(--surface);z-index:2}.service-translations{display:flex;flex-direction:column;gap:12px;padding-top:14px}.service-editor :global(summary){padding:9px 12px}</style>
